@main
enum PhysicalFactsQualification {
    static func main() {
        if CommandLine.arguments.dropFirst().first == "--missing-row-fatal" {
            p08CounterPhysicalFactsMissingRowsFatal()
            preconditionFailure("expected missing-row precondition")
        }
        let checks = p08CounterPhysicalFactsQualification()
        precondition(checks > 0)
        print(
            "physical facts Static/Dynamic independent rows, five banks, 26 totals, audits, mismatch, refusal, faults, surplus, destruction PASS checks=\(checks)"
        )
    }
}

exact_fatal_path_source:
package func p08CounterPhysicalFactsMissingRowsFatal() {
    var models = ObservableModelOwnerNamespace(), semantics = SemanticRecordOwnerNamespace()
    do {
        withP08SelectedStatic(modelOwner: try models.issue(), semanticOwner: try semantics.issue(), backing: nil) { owner, outer, _ in
            let reference = owner.originalPhysicalFactsForQualification()
            let malformed = P08OwnedPhysicalFacts(geometry: reference.geometry, geometryRegions: .init(), interaction: reference.interaction)
            _ = outer.audit(facts: malformed, report: { _ in })
            preconditionFailure("missing physical row audit returned")
        }
    } catch { preconditionFailure("physical facts namespaces") }
}
